const COMMON_FALLBACK = "Think concisely. Keep internal reasoning brief and focused on the immediate step. Output tool calls directly without conversational filler.";

export function commonBody(root?: string): string {
	const path = join(root ?? defaultSourcesRoot(), "common.md");
	if (existsSync(path)) return readFileSync(path, "utf8").trim();
	return COMMON_FALLBACK;
}

export function isPlanHarness(name: string): boolean {
	return name.endsWith("-plan");
}

